87:   public ManagedProcess launch(AbstractCommand command) {
88:     EsInstallation esInstallation = command.getEsInstallation();
89:     if (esInstallation != null) {
90:       cleanupOutdatedEsData(esInstallation);
91:       writeConfFiles(esInstallation);
92:     }
93: 
94:     Process process;
95:     if (command instanceof JavaCommand<?> javaCommand) {
96:       process = launchJava(javaCommand);
97:     } else {
98:       throw new IllegalStateException("Unexpected type of command: " + command.getClass());
99:     }
100: 
101:     ProcessId processId = command.getProcessId();
102:     try {
103:       if (processId == ProcessId.ELASTICSEARCH) {
104:         checkArgument(esInstallation != null, "Incorrect configuration EsInstallation is null");
105:         EsConnectorImpl esConnector = new EsConnectorImpl(singleton(HostAndPort.fromParts(esInstallation.getHost(),
106:           esInstallation.getHttpPort())), esInstallation.getBootstrapPassword(), esInstallation.getHttpKeyStoreLocation(),
107:           esInstallation.getHttpKeyStorePassword().orElse(null));
108:         return new EsManagedProcess(process, processId, esConnector);
109:       } else {
110:         ProcessCommands commands = allProcessesCommands.createAfterClean(processId.getIpcIndex());
111:         return new ProcessCommandsManagedProcess(process, processId, commands);
112:       }
113:     } catch (Exception e) {
114:       // just in case
115:       if (process != null) {
116:         process.destroyForcibly();
117:       }
118:       throw new IllegalStateException(format("Fail to launch monitor of process [%s]", processId.getHumanReadableName()), e);
119:     }
120:   }
