123:     esInstallation.getOutdatedSearchDirectories()
124:       .forEach(outdatedDir -> {
125:         if (outdatedDir.exists()) {
126:           LOG.info("Deleting outdated search index data directory {}", outdatedDir.getAbsolutePath());
127:           try {
