170:   private void setupElasticsearchSecurity(EsInstallation esInstallation) {
171:     if (esInstallation.isSecurityEnabled()) {
172:       EsKeyStoreCli keyStoreCli = EsKeyStoreCli.getInstance(esInstallation);
173: 
174:       setupElasticsearchAuthentication(esInstallation, keyStoreCli);
175:       setupElasticsearchHttpEncryption(esInstallation, keyStoreCli);
176: 
177:       keyStoreCli.executeWith(this::launchJava);
178:     }
179:   }
