181:   private static void setupElasticsearchAuthentication(EsInstallation esInstallation, EsKeyStoreCli keyStoreCli) {
182:     keyStoreCli.store(BOOTSTRAP_PASSWORD_PROPERTY_KEY, esInstallation.getBootstrapPassword());
183: 
184:     String esConfPath = esInstallation.getConfDirectory().getAbsolutePath();
185: 
186:     Path trustStoreLocation = esInstallation.getTrustStoreLocation();
187:     Path keyStoreLocation = esInstallation.getKeyStoreLocation();
188:     if (trustStoreLocation.equals(keyStoreLocation)) {
189:       copyFile(trustStoreLocation, Paths.get(esConfPath, trustStoreLocation.toFile().getName()));
190:     } else {
191:       copyFile(trustStoreLocation, Paths.get(esConfPath, trustStoreLocation.toFile().getName()));
192:       copyFile(keyStoreLocation, Paths.get(esConfPath, keyStoreLocation.toFile().getName()));
193:     }
194: 
195:     esInstallation.getTrustStorePassword().ifPresent(s -> keyStoreCli.store(TRUSTSTORE_PASSWORD_PROPERTY_KEY, s));
196:     esInstallation.getKeyStorePassword().ifPresent(s -> keyStoreCli.store(KEYSTORE_PASSWORD_PROPERTY_KEY, s));
197:   }
