201:       String esConfPath = esInstallation.getConfDirectory().getAbsolutePath();
202:       Path httpKeyStoreLocation = esInstallation.getHttpKeyStoreLocation();
203:       copyFile(httpKeyStoreLocation, Paths.get(esConfPath, httpKeyStoreLocation.toFile().getName()));
