224:   private <T extends JvmOptions> Process launchJava(JavaCommand<T> javaCommand) {
225:     ProcessId processId = javaCommand.getProcessId();
226:     try {
227:       ProcessBuilder processBuilder = create(javaCommand);
228:       logLaunchedCommand(javaCommand, processBuilder);
229:       return processBuilder.start();
230:     } catch (Exception e) {
231:       throw new IllegalStateException(format("Fail to launch process [%s]", processId.getHumanReadableName()), e);
232:     }
233:   }
