235:   private static <T extends AbstractCommand> void logLaunchedCommand(AbstractCommand<T> command, ProcessBuilder processBuilder) {
236:     LOG.atInfo()
237:       .addArgument(command::getProcessId)
238:       .addArgument(() -> command.getWorkDir().getAbsolutePath())
239:       .addArgument(() -> String.join(" ", processBuilder.command()))
240:       .log("Launch process[{}] from [{}]: {}");
241:   }
