243:   private <T extends JvmOptions> ProcessBuilder create(JavaCommand<T> javaCommand) {
244:     List<String> commands = new ArrayList<>();
245:     commands.add(buildJavaPath());
246:     commands.addAll(javaCommand.getJvmOptions().getAll());
247:     commands.addAll(buildClasspath(javaCommand));
248:     commands.add(javaCommand.getClassName());
249:     commands.addAll(javaCommand.getParameters());
250: 
251:     if (javaCommand.getReadsArgumentsFromFile()) {
252:       commands.add(buildPropertiesFile(javaCommand).getAbsolutePath());
253:     } else {
254:       javaCommand.getArguments().forEach((key, value) -> {
255:         if (value != null && !value.isEmpty()) {
256:           commands.add("-E" + key + "=" + value);
257:         }
258:       });
259:     }
260: 
261:     return create(javaCommand, commands);
262:   }
263: 
264:   private ProcessBuilder create(AbstractCommand<?> command, List<String> commands) {
265:     ProcessBuilder processBuilder = processBuilderSupplier.get();
266:     processBuilder.command(commands);
267:     processBuilder.directory(command.getWorkDir());
268:     Map<String, String> environment = processBuilder.environment();
269:     environment.putAll(command.getEnvVariables());
270:     command.getSuppressedEnvVariables().forEach(environment::remove);
271:     processBuilder.redirectErrorStream(true);
272:     return processBuilder;
273:   }
