280:   private static <T extends JvmOptions> List<String> buildClasspath(JavaCommand<T> javaCommand) {
281:     String pathSeparator = System.getProperty("path.separator");
282:     return Arrays.asList("-cp", String.join(pathSeparator, javaCommand.getClasspath()));
283:   }
