285:   private File buildPropertiesFile(JavaCommand javaCommand) {
286:     File propertiesFile = null;
287:     try {
288:       propertiesFile = File.createTempFile("sq-process", "properties", tempDir);
289:       Properties props = new Properties();
290:       props.putAll(javaCommand.getArguments());
291:       props.setProperty(PROPERTY_PROCESS_KEY, javaCommand.getProcessId().getKey());
292:       props.setProperty(PROPERTY_PROCESS_INDEX, Integer.toString(javaCommand.getProcessId().getIpcIndex()));
293:       props.setProperty(PROPERTY_GRACEFUL_STOP_TIMEOUT_MS, javaCommand.getGracefulStopTimeoutMs() + "");
294:       props.setProperty(PROPERTY_SHARED_PATH, tempDir.getAbsolutePath());
295:       try (OutputStream out = new FileOutputStream(propertiesFile)) {
296:         props.store(out, format("Temporary properties file for command [%s]", javaCommand.getProcessId().getKey()));
297:       }
298:       return propertiesFile;
299:     } catch (Exception e) {
300:       throw new IllegalStateException("Cannot write temporary settings to " + propertiesFile, e);
301:     }
302:   }
